-- ----------------------------
-- Table structure for TB_USERS
-- ----------------------------
DROP TABLE IF EXISTS `TB_USERS`;
CREATE TABLE `TB_USERS`  (
  `ID` bigint NOT NULL COMMENT '主键id',
  `USER_ID` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '用户id',
  `PASSWORD` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '123456' COMMENT '登录密码',
  `EMAIL` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '用户EMAIL',
  `ROLE` int NOT NULL COMMENT '用户角色 1：超级管理员 2：管理员 3：普通用户',
  `CREATE_TIME` datetime NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人',
  `UPDATE_TIME` datetime NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新人',
  `DELETE_FLAG` bit(1) NOT NULL DEFAULT b'0' COMMENT '删除标识',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = DYNAMIC;

